/// <reference path="../types/untypedModules.d.ts" />
import uuid = require('uuid')
const uuidv4 = uuid.v4
import sequelize = require('sequelize')
import type { BuildOptions, CreationAttributes, Sequelize } from 'sequelize'
import lruCache = require('lru-cache')
const { LRUCache } = lruCache

import Logger = require('../Logger')
import SocketAuthority = require('../SocketAuthority')
import utils = require('../utils')
const { isNullOrNaN }: { isNullOrNaN: (num: unknown) => boolean } = utils
import TokenManager = require('../auth/TokenManager')

declare const global: typeof globalThis & { ServerSettings: { authOpenIDMatchExistingBy: string | null } }

type LibraryItem = import('./LibraryItem')
type MediaProgress = import('./MediaProgress')

/** Registry entries this file reads by name, with their model classes */
type RegisteredModels = { podcastEpisode: typeof import('./PodcastEpisode'); mediaProgress: typeof import('./MediaProgress') }

// Type-only: keeps import('./User').ProgressUpdatePayload (read by models/MediaProgress.ts) resolvable after export = User
declare namespace User {
  interface AudioBookmarkObject {
    libraryItemId: string
    title: string
    time: number
    createdAt: number
  }
  interface ProgressUpdatePayload {
    libraryItemId: string
    episodeId?: string
    duration?: number
    progress?: number
    currentTime?: number
    isFinished?: boolean
    hideFromContinueListening?: boolean
    ebookLocation?: string
    ebookProgress?: number
    finishedAt?: string
    lastUpdate?: number
    markAsFinishedTimeRemaining?: number
    markAsFinishedPercentComplete?: number
    createdAt?: string | number // read by createUpdateMediaProgressFromPayload(); the JSDoc typedef does not list it
  }
}
type AudioBookmarkObject = User.AudioBookmarkObject
type ProgressUpdatePayload = User.ProgressUpdatePayload

